package com.example.fulfillmentservice.model;import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.index.Indexed;import org.springframework.data.mongodb.core.mapping.Document;import java.time.Instant;@Document("fulfillments")public class Fulfillment{@Id private String id;@Indexed(unique=true)private String orderId;private String customerId,productId,trackingNumber;private FulfillmentStatus status;private Instant createdAt,nextTransitionAt,deliveredAt,statusChangedAt;private String statusReason;public Instant getStatusChangedAt(){return statusChangedAt;}public void setStatusChangedAt(Instant v){statusChangedAt=v;}public String getStatusReason(){return statusReason;}public void setStatusReason(String v){statusReason=v;}public String getId(){return id;}public String getOrderId(){return orderId;}public void setOrderId(String v){orderId=v;}public String getCustomerId(){return customerId;}public void setCustomerId(String v){customerId=v;}public String getProductId(){return productId;}public void setProductId(String v){productId=v;}public String getTrackingNumber(){return trackingNumber;}public void setTrackingNumber(String v){trackingNumber=v;}public FulfillmentStatus getStatus(){return status;}public void setStatus(FulfillmentStatus v){status=v;}public Instant getCreatedAt(){return createdAt;}public void setCreatedAt(Instant v){createdAt=v;}public Instant getNextTransitionAt(){return nextTransitionAt;}public void setNextTransitionAt(Instant v){nextTransitionAt=v;}public Instant getDeliveredAt(){return deliveredAt;}public void setDeliveredAt(Instant v){deliveredAt=v;}}
